#!/usr/bin/env python3
"""Recompute deterministic dust-veil numeric ground truth for CSX-300_Q2."""

from __future__ import annotations

import json
import warnings
from pathlib import Path
from typing import Any, Iterable, Iterator

from PIL import Image


TASK_ID = "CSX-300_Q2"
PACKAGE_ID = "CSX-300"
TARGET_FAMILY = "australia_2009_dust_tan_brightening_dry_wind_consistency"


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID


def read_json(root: Path, rel_path: str) -> Any:
    return json.loads((root / rel_path).read_text(encoding="utf-8-sig"))


def rounded(value: float, digits: int) -> float:
    return round(float(value), digits)


def pixel_data(image: Image.Image) -> Iterable[Any]:
    flattened = getattr(image, "get_flattened_data", None)
    if callable(flattened):
        return flattened()
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", DeprecationWarning)
        return image.getdata()


def iter_rgb_pixels(image: Image.Image) -> Iterator[tuple[int, int, int]]:
    iterator = iter(pixel_data(image))
    for pixel in iterator:
        if isinstance(pixel, (tuple, list)):
            if len(pixel) < 3:
                raise ValueError("RGB pixel record has fewer than three channels")
            yield int(pixel[0]), int(pixel[1]), int(pixel[2])
        else:
            red = int(pixel)
            green = int(next(iterator))
            blue = int(next(iterator))
            yield red, green, blue


def image_metrics(root: Path, rel_path: str) -> dict[str, Any]:
    image = Image.open(root / rel_path).convert("RGB")
    red_sum = green_sum = blue_sum = 0
    tan_pixels = 0
    red_excess_sum = 0.0
    count = 0

    for red, green, blue in iter_rgb_pixels(image):
        count += 1
        red_sum += red
        green_sum += green
        blue_sum += blue
        if red > green > blue and red > 120 and green > 90 and blue < 170:
            tan_pixels += 1
        red_excess_sum += red - blue

    mean_red = red_sum / count
    mean_green = green_sum / count
    mean_blue = blue_sum / count
    return {
        "width": image.width,
        "height": image.height,
        "mean_rgb": [rounded(mean_red, 3), rounded(mean_green, 3), rounded(mean_blue, 3)],
        "mean_luminance": rounded((mean_red + mean_green + mean_blue) / 3.0, 3),
        "tan_fraction": rounded(tan_pixels / count, 4),
        "red_excess": rounded(red_excess_sum / count, 4),
    }


def point_weather_metrics(root: Path) -> dict[str, float]:
    power = read_json(root, "data/physical_hazard/physical_hazard_001_NASA_POWER_daily_point_sample.json")
    open_meteo = read_json(root, "data/physical_hazard/physical_hazard_002_Open-Meteo_archive_point_sample.json")

    power_params = power["properties"]["parameter"]
    power_precip = sum(float(value) for value in power_params["PRECTOTCORR"].values())
    power_wind = max(float(value) for value in power_params["WS10M"].values())

    daily = open_meteo["daily"]
    open_meteo_precip = sum(float(value) for value in daily["precipitation_sum"])
    open_meteo_wind = max(float(value) for value in daily["wind_speed_10m_max"]) / 3.6

    point_precip_total = rounded(power_precip + open_meteo_precip, 3)
    max_point_wind = rounded(max(power_wind, open_meteo_wind), 3)
    return {
        "point_precip_total_mm": point_precip_total,
        "max_point_wind_m_s": max_point_wind,
        "dry_wind_index": rounded(max_point_wind / (1.0 + point_precip_total), 3),
    }


def regional_precip_metrics(root: Path) -> dict[str, float]:
    gpm = read_json(root, "data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json")
    stats = gpm["stats"]
    return {
        "regional_precip_mean_mm": stats["gpm_event_precip_mm_mean"],
        "regional_precip_max_mm": stats["gpm_event_precip_mm_max"],
    }


def build_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Answer form",
                "points": 3,
                "description": "Returns compact JSON with the requested numeric fields, classification, and one short interpretation.",
                "partial_credit": "Award 1-2 points if the numeric answer is recoverable but field names or nesting differ.",
            },
            {
                "name": "Pixel formulas",
                "points": 3,
                "description": "Uses mean luminance, tan-pixel fraction, and mean red-minus-blue excess exactly as defined.",
                "partial_credit": "Award 1-2 points for using two of the three formulas correctly.",
            },
            {
                "name": "Image deltas",
                "points": 5,
                "description": "Reports the event-minus-pre values within tolerance: luminance +31.226, tan fraction +0.0245, and red excess +2.4108.",
                "partial_credit": "Award about 1.5 points per correct delta, with small rounding tolerance.",
            },
            {
                "name": "Dry-wind calculation",
                "points": 3,
                "description": "Computes package point precipitation as 0.0 mm, maximum package point wind as 11.639 m/s, and dry-wind index as 11.639 while treating point weather as a dry-wind comparator.",
                "partial_credit": "Award 1-2 points for correct dry or wind components with an error in the combined index.",
            },
            {
                "name": "Threshold score",
                "points": 4,
                "description": "Applies all four threshold tests and returns dust_veil_score = 4 with the dry_wind_tan_brightening_dust_veil classification.",
                "partial_credit": "Award 1 point per correctly evaluated threshold test.",
            },
            {
                "name": "Computed consequence",
                "points": 2,
                "description": "Rejects a rainfall or wet-surface reading from the near-zero precipitation and avoids treating the image metric as calibrated dust concentration.",
                "partial_credit": "Award 1 point for either the wet-surface rejection or the calibration caution.",
            },
        ],
    }


def source_files() -> list[str]:
    return [
        "metadata/event.json",
        "data/event_reports/event_reports_003_Locked_event_anchor_September_2009_Australian_dust_storm.json",
        "data/remote_sensing/remote_sensing_002_pre.jpg",
        "data/remote_sensing/remote_sensing_003_event.jpg",
        "data/physical_hazard/physical_hazard_001_NASA_POWER_daily_point_sample.json",
        "data/physical_hazard/physical_hazard_002_Open-Meteo_archive_point_sample.json",
        "data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json",
    ]


def build_output() -> dict[str, Any]:
    root = package_root()
    event = read_json(root, "metadata/event.json")
    anchor = read_json(
        root,
        "data/event_reports/event_reports_003_Locked_event_anchor_September_2009_Australian_dust_storm.json",
    )
    pre = image_metrics(root, "data/remote_sensing/remote_sensing_002_pre.jpg")
    event_image = image_metrics(root, "data/remote_sensing/remote_sensing_003_event.jpg")
    point_weather = point_weather_metrics(root)
    regional_precip = regional_precip_metrics(root)

    luminance_delta = rounded(event_image["mean_luminance"] - pre["mean_luminance"], 3)
    tan_fraction_delta = rounded(event_image["tan_fraction"] - pre["tan_fraction"], 4)
    red_excess_delta = rounded(event_image["red_excess"] - pre["red_excess"], 4)

    thresholds = {
        "luminance_delta_min": 25,
        "tan_fraction_delta_min": 0.02,
        "red_excess_delta_min": 2,
        "dry_wind_index_min": 10,
        "point_precip_total_max_mm": 0.5,
    }
    tests = {
        "luminance_delta": luminance_delta >= thresholds["luminance_delta_min"],
        "tan_fraction_delta": tan_fraction_delta >= thresholds["tan_fraction_delta_min"],
        "red_excess_delta": red_excess_delta >= thresholds["red_excess_delta_min"],
        "dry_wind": (
            point_weather["point_precip_total_mm"] <= thresholds["point_precip_total_max_mm"]
            and point_weather["dry_wind_index"] >= thresholds["dry_wind_index_min"]
        ),
    }
    score = sum(1 for passed in tests.values() if passed)
    classification = "dry_wind_tan_brightening_dust_veil" if score == 4 else "mixed_or_weak_dust_signal"

    metrics = {
        "pre_mean_luminance": pre["mean_luminance"],
        "event_mean_luminance": event_image["mean_luminance"],
        "luminance_delta": luminance_delta,
        "tan_fraction_delta": tan_fraction_delta,
        "red_excess_delta": red_excess_delta,
        "dry_wind_index": point_weather["dry_wind_index"],
        "dust_veil_score": score,
        "classification": classification,
    }
    interpretation = (
        "All four tests pass, so the computed consequence is a dry, wind-supported tan "
        "brightening signal rather than a rainfall or wet-surface signal."
    )

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": PACKAGE_ID,
        "target_family": TARGET_FAMILY,
        "task_type": "numeric",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": {
            "answer": metrics,
            "interpretation": interpretation,
            "canonical_answer": classification,
            "tolerances": {
                "pre_mean_luminance": 0.005,
                "event_mean_luminance": 0.005,
                "luminance_delta": 0.005,
                "tan_fraction_delta": 0.0002,
                "red_excess_delta": 0.0002,
                "dry_wind_index": 0.005,
                "dust_veil_score": 0,
            },
            "thresholds": thresholds,
            "rejected": "rainfall_wet_surface_signal",
            "evidence_roles": {
                "image_pair": "dust-veil color and brightness tests",
                "package_point_weather": "dry-wind comparator only",
                "regional_precipitation": "supporting wetness context only",
            },
        },
        "event": {
            "package_id": PACKAGE_ID,
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": (
                f"{anchor['temporal_window']['start_date']} to {anchor['temporal_window']['end_date']}"
            ),
            "location": anchor["spatial_window"]["location_text"],
        },
        "decision_rule": {
            "summary": "Classify the event image pair by thresholded tan brightening plus a dry-wind index.",
            "requires_computation": True,
            "score_rule": "One point for each passed threshold; score 4 gives the dust-veil classification.",
            "tests": tests,
        },
        "key_values": {
            "pre_image": pre,
            "event_image": event_image,
            "image_deltas": {
                "luminance_delta": luminance_delta,
                "tan_fraction_delta": tan_fraction_delta,
                "red_excess_delta": red_excess_delta,
            },
            "point_weather": point_weather,
            "regional_precip": regional_precip,
            "threshold_tests": tests,
            "classification": classification,
        },
        "numeric_tolerances": {
            key: {
                "target": value,
                "absolute_tolerance": {
                    "pre_mean_luminance": 0.005,
                    "event_mean_luminance": 0.005,
                    "luminance_delta": 0.005,
                    "tan_fraction_delta": 0.0002,
                    "red_excess_delta": 0.0002,
                    "dry_wind_index": 0.005,
                    "dust_veil_score": 0,
                }[key],
            }
            for key, value in metrics.items()
            if key != "classification"
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": source_files(),
            "notes": "All numeric anchors are recomputed from local CSX-300 image and weather data.",
        },
        "supporting_metrics": {
            "point_weather_scope": "package point-weather values are used only as dry-wind comparators, not as complete corridor wind evidence"
        },
    }


def main() -> None:
    output_path = Path(__file__).resolve().parent / "computed_gt.json"
    output_path.write_text(json.dumps(build_output(), indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
